:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-button: #f6f5f3;
  --color-sand-card: #eae7e1;
  --color-fog-tile: #e3e3e3;
  --color-carbon-slate: #2d3636;
  --color-jet-ink: #000000;
  --color-onyx-heading: #080808;
  --color-pewter-caption: #777777;
  --color-stone-border: #c7c4be;
  --color-frosted-hairline: #ffffff40;
  --color-keylime-signal: #a3fda7;
  --color-forest-pulse: #219e73;
  --color-mint-wash: #f2ffe3;

  /* Typography — Font Families */
  --font-main-font: "mainFont", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-secondary-font: "secondaryFont", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 9px;
  --leading-small: 1.2;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.5;
  --tracking-caption: 0px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.2;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.2;
  --tracking-subheading: -0.24px;
  --text-heading-sm: 30px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: -0.9px;
  --text-heading: 54px;
  --leading-heading: 1.05;
  --tracking-heading: -0.54px;
  --text-heading-lg: 80px;
  --leading-heading-lg: 1.02;
  --tracking-heading-lg: -0.8px;
  --text-display: 120px;
  --leading-display: 0.95;
  --tracking-display: -1.2px;

  /* Typography — Weights */
  --font-weight-thin: 100; /* display numerals only */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-19: 19px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-30: 30px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-60: 60px;
  --spacing-70: 70px;
  --spacing-80: 80px;

  /* Layout */
  --layout-max-width: 1200px;
  --layout-frame-width: 1960px;
  --layout-section-gap: 80px;
  --layout-card-padding: 32px;
  --layout-element-gap: 12px;
  --layout-nav-height: 85px;
  --layout-control-height: 47px;
  --layout-arrow-size: 48px;

  /* Border Radius */
  --radius-sm: 10px;
  --radius-md: 20px;
  --radius-lg: 24px;
  --radius-full: 100px;

  /* Named Radii */
  --radius-buttons: 10px;
  --radius-images: 10px;
  --radius-inner-tiles: 10px;
  --radius-cards: 20px;
  --radius-sections: 24px;
  --radius-inputs: 100px;
  --radius-tags: 100px;
  --radius-pills: 100px;
  --radius-small-elements: 50%;

  /* Shadows */
  --shadow-md: 0px 14px 32px -20px rgba(0, 0, 0, 0.22), 0px 3px 10px -6px rgba(0, 0, 0, 0.1);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-button: #f6f5f3;
  --surface-sand-card: #eae7e1;
  --surface-carbon-slate: #2d3636;
}

